{"version":3,"sources":["index.js"],"sourcesContent":["import { createRouter, createWebHistory } from "/node_modules/.vite/deps/vue-router.js?v=131fab45"

const routes = [
  {
    path: '/login',
    name: 'Login',
    component: () => import("/src/views/Login.vue"),
    meta: { public: true },
  },
  {
    path: '/',
    component: () => import("/src/views/Layout.vue"),
    meta: { requiresAuth: true },
    children: [
      { path: '', redirect: '/dashboard' },
      { path: 'dashboard', name: 'Dashboard', component: () => import("/src/views/Dashboard.vue") },
      { path: 'users', name: 'Users', component: () => import("/src/views/Users.vue") },
      { path: 'posts', name: 'Posts', component: () => import("/src/views/Posts.vue") },
      { path: 'posts/new', name: 'PostNew', component: () => import("/src/views/PostEdit.vue") },
      { path: 'posts/:id/edit', name: 'PostEdit', component: () => import("/src/views/PostEdit.vue") },
      { path: 'media', name: 'Media', component: () => import("/src/views/Media.vue") },
      { path: 'settings', name: 'Settings', component: () => import("/src/views/Settings.vue") },
    ],
  },
  { path: '/:pathMatch(.*)*', redirect: '/dashboard' },
]

const router = createRouter({
  history: createWebHistory(),
  routes,
})

router.beforeEach((to) => {
  const token = localStorage.getItem('token')
  if (to.meta.requiresAuth && !token) {
    return { path: '/login', query: { redirect: to.fullPath } }
  }
  if (to.meta.public && token) {
    return { path: '/dashboard' }
  }
})

export default router
